    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best = None
    best_vector = None

    def is_acyclic(graph, installed):
        active = set()
        finished = set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in graph.get(name, []):
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        return all(visit(name) for name in installed)

    def search(chosen, requirements, graph):
        nonlocal best, best_vector
        pending = [name for name in requirements if name not in chosen]
        if not pending:
            if not is_acyclic(graph, chosen):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            better = (best_vector is None or
                      (vector > best_vector if preference == "maximum"
                       else vector < best_vector))
            if better:
                best = dict(chosen)
                best_vector = vector
            return

        name = min(pending)
        low, high = requirements[name]
        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        rows.sort(key=lambda row: row["version"],
                reverse=(preference == "maximum"))

        for row in rows:
            version = row["version"]
            dependencies = [dep for dep in row.get("deps", [])
                            if not dep.get("feature")
                            or dep["feature"] in features]
            next_requirements = dict(requirements)
            next_graph = dict(graph)
            next_graph[name] = []
            valid = True

            for dep in dependencies:
                other = dep["name"]
                bounds = (dep["min"], dep["max"])
                if other in next_requirements:
                    old_low, old_high = next_requirements[other]
                    bounds = (max(old_low, bounds[0]),
                              min(old_high, bounds[1]))
                if bounds[0] > bounds[1]:
                    valid = False
                    break
                next_requirements[other] = bounds
                next_graph[name].append(other)
                if other in chosen and not bounds[0] <= chosen[other] <= bounds[1]:
                    valid = False
                    break

            if valid:
                next_chosen = dict(chosen)
                next_chosen[name] = version
                search(next_chosen, next_requirements, next_graph)

    search({}, {name: tuple(bounds) for name, bounds in data["roots"].items()}, {})
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _build_dependency(name_order, preference):
    return lambda data: _dependency_solver(data, name_order, preference)


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000,
                          data["rounding"])
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}

    return solve


def _build_component_07():
    from itertools import combinations

    def compatible(jobs):
        active_ends = []
        for job in sorted(jobs, key=lambda item: (item["start"], item["end"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                return False
        return True

    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        if len(mandatory) > k or any(job_id in blocked for job_id in mandatory):
            return {"error": "impossible"}

        best_ids = None
        best_value = None
        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids) or not compatible(subset):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered_ids = tuple(sorted(ids))
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and ordered_ids < best_ids)):
                best_value, best_ids = value, ordered_ids

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}

    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        indexes = {node: i for i, node in enumerate(required)}
        full_mask = (1 << len(required)) - 1
        start = data["source"]
        initial_mask = 1 << indexes[start] if start in indexes else 0
        initial_state = (start, initial_mask, data["coupons"])
        distances = {initial_state: data["start"]}
        queue = [(data["start"], start, initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, coupons = heapq.heappop(queue)
            state = (node, mask, coupons)
            if time != distances.get(state):
                continue
            if node == data["target"] and mask == full_mask:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], coupons)]
                if coupons:
                    reduced = max(2, edge["duration"] - edge.get("discount", 0))
                    choices.append((reduced, coupons - 1))
                for duration, remaining in choices:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_mask = mask | (1 << indexes[nxt] if nxt in indexes else 0)
                    next_state = (nxt, next_mask, remaining)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, next_mask, remaining))

        return {"arrival": None}

    return solve


